\"\"\"Private OpenAI Responses API client using only the Python standard library.

Send private text prompts to OpenAI's Responses API
(https://platform.openai.com/docs/api-reference/responses) without any
third-party dependencies. The API key is read from the "'``OPENAI_API_KEY``
environment variable and is never written to disk by this module.

Example
-------
>>> from openai_client import send_prompt
>>> print(send_prompt("Say hello in one word."))
"""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request

__all__ = ["ResponsesClient", "send_prompt", "OpenAIError"]

DEFAULT_MODEL = "gpt-4o-mini"
API_URL = "https://api.openai.com/v1/responses"


class OpenAIError(RuntimeError):
    """Raised when the Responses API request fails."""


def _build_request(payload: dict, api_key: str) -> urllib.request.Request:
    data = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(API_URL, data=data, method="POST")
    request.add_header("Content-Type", "application/json")
    request.add_header("Authorization", f"Bearer {api_key}")
    return request


def _parse_response(raw: bytes) -> str:
    try:
        body = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise OpenAIError(f"Invalid JSON response: {exc}") from exc

    if "error" in body:
        raise OpenAIError(body["error"].get("message", str(body["error"])))

    parts = []
    for item in body.get("output", []):
        if item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if content.get("type") == "output_text":
                parts.append(content.get("text", ""))
    return "'"\\n\".join(parts).strip()


class ResponsesClient:
    \"\"\"Minimal client for OpenAI's Responses API.\"\"\"

    def __init__(self, api_key: str | None = None, model: str = DEFAULT_MODEL):
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\", \"\")
        if not self.api_key:
            raise OpenAIError(\"OPENAI_API_KEY is not set\")
        self.model = model

    def send(self, text: str, instructions: str | None = None) -> str:
        payload = {\"model\": self.model, \"input\": text}
        if instructions:
            payload[\"instructions\"] = instructions
        try:
            with urllib.request.urlopen(
                _build_request(payload, self.api_key), timeout=60
            ) as resp:
                return _parse_response(resp.read())
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode(\"utf-8\", \"replace\")
            raise OpenAIError(f\"HTTP {exc.code}: {detail}\") from exc
        except urllib.error.URLError as exc:
            raise OpenAIError(f\"Network error: {exc.reason}\") from exc


def send_prompt(
    text: str,
    *,
    model: str = DEFAULT_MODEL,
    api_key: str | None = None,
    instructions: str | None = None,
) -> str:
    \"\"\"Send a single private text prompt and return the model's reply.\"\"\"
    return ResponsesClient(api_key=[REDACTED_SECRET] model=model).send(
        text, instructions=instructions
    )


if __name__ == \"__main__\":
    import sys

    prompt = \" \".join(sys.argv[1:]) or \"Say hello in one word.\"
    print(send_prompt(prompt))
